insert into policies (id, workspace_id, code, name_en, vision, start_date, end_date, approved_on, approved_by, owner_ministry_id, status) values
  ('8820e37f-9611-5f70-9e17-07338290e329', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', 'NCP-2022', 'National Cashew Policy 2022–2027', 'Develop cashew production, processing and markets through inclusive competitiveness to ensure sustainability and economic diversification, making Cambodia a major producer and supplier of cashew products for local, regional and global markets.', '2022-01-01', '2027-12-31', '2023-01-13', 'Council of Ministers (plenary session)', 'cdd4851c-2d8a-53a4-bd83-8708af3a0c34', 'active');
