insert into actions (id, workspace_id, policy_id, programme_id, cluster_id, number, code, title_en, responsible_text, status) values
  ('11180143-9829-5152-ab39-04ef2d38b52c', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '6bc9a480-05d6-5f6a-8aa0-df07fc6d4c87', 'e702018a-6286-5577-805f-f99d921df07d', 1, 'ACT-01', 'Disseminate new discoveries to farmers through the website of the Agricultural Information and Documentation Centre or on social media, setting up a platform where farmers can share their ideas and experiences.', 'MAFF', 'active'),
  ('6886224c-05d4-5b0e-be37-040da73d61aa', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '6bc9a480-05d6-5f6a-8aa0-df07fc6d4c87', 'e702018a-6286-5577-805f-f99d921df07d', 2, 'ACT-02', 'Continue to conduct scientific research on cashew varieties, especially new varieties that are in line with Cambodia''s ecosystem, climate / change, and target market needs.', 'MAFF', 'active'),
  ('7c788e2c-cc3c-5416-9568-ea1bf9f7d64a', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '6bc9a480-05d6-5f6a-8aa0-df07fc6d4c87', 'e702018a-6286-5577-805f-f99d921df07d', 3, 'ACT-03', 'Implement the development and improvement of annual production measurement methods based on the latest available survey data - plantation yields; production costs; agro-input use; the investment level; the age of cashew trees; newly planted varieties; new plantings; and pests – in order to increase cashew production, as well as calculate production and identify potential for improvement.', 'MAFF', 'active'),
  ('c54ff2d2-534f-5858-a7fb-0044943f38fb', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '6bc9a480-05d6-5f6a-8aa0-df07fc6d4c87', 'e702018a-6286-5577-805f-f99d921df07d', 4, 'ACT-04', 'Prepare guidelines and disseminate to farmers and farm owners how to dry, grade, and store cashew nuts properly in accordance with technical conditions to ensure good quality and safety.', 'MAFF', 'active'),
  ('b2d090f0-926a-5877-8796-1823d7d3c10b', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '6bc9a480-05d6-5f6a-8aa0-df07fc6d4c87', 'e702018a-6286-5577-805f-f99d921df07d', 5, 'ACT-05', 'Strengthen the implementation of existing regulations and assess environmental risks in the management of raw agricultural materials, especially pesticides, in order to optimise cashew productivity in accordance with technical standards.', 'MAFF, MOE', 'active'),
  ('f65576f7-933f-5237-8d0c-82a42c180785', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '6bc9a480-05d6-5f6a-8aa0-df07fc6d4c87', 'e702018a-6286-5577-805f-f99d921df07d', 6, 'ACT-06', 'Increase productivity and protect the safety of farmers and farm workers through technical training, both theoretical and practical, to improve the quality of services, good agricultural practices and organic farming to be more accurate and effective in the cashew sector.', 'MAFF', 'active'),
  ('b1def8b5-871e-524b-a070-cc38cd4749cb', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '6bc9a480-05d6-5f6a-8aa0-df07fc6d4c87', 'e702018a-6286-5577-805f-f99d921df07d', 7, 'ACT-07', 'Recommend the establishment of a collective production group and a clear data collection study to identify the source of Cambodian cashew products in the market.', 'MAFF, MOC, OVOP, / MAFF', 'active'),
  ('0cc43a05-44b1-5e4f-b795-4e7f3f0e46be', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '6d5fbf8b-d9f7-528a-a3b7-058588a92334', 'e702018a-6286-5577-805f-f99d921df07d', 8, 'ACT-08', 'Guide and coordinate the establishment of agricultural communities based on cashew crops and strengthen agricultural communities to function well.', 'MAFF, MOC, OVOP, / MAFF', 'active'),
  ('7f5a015a-8a7d-54d9-b4cf-9b4c5d1b94ab', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '07b55b8f-8ff2-5485-b93c-3c894fc3bfcc', 'e702018a-6286-5577-805f-f99d921df07d', 9, 'ACT-09', 'Coordinate the establishment of a Cashew Association and Federation.', 'MOI, MOC', 'active'),
  ('0e123f14-4425-5822-a9f5-e9b389b27a11', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '6bc9a480-05d6-5f6a-8aa0-df07fc6d4c87', 'e702018a-6286-5577-805f-f99d921df07d', 10, 'ACT-10', 'Strengthen farming contracts to ensure the supply chain by increasing value-added both during and post-harvest season through links between agricultural associations, farmer groups, and local processors for commercialisation in Cambodia.', 'MAFF, MOC, Provincial', 'active'),
  ('febfeb98-cac5-5038-bf72-a7a99927433a', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '69152697-bb7b-5e6c-814c-c8362f1c9c25', 'e702018a-6286-5577-805f-f99d921df07d', 11, 'ACT-11', 'Strengthen the reputation of cashew products by improving the quality, taste, and the use of chemical inputs in accordance with technical standards in production.', 'MOC, MAFF', 'active'),
  ('e8c3aca7-c1fc-5069-a54f-f1929d375d5a', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '6bc9a480-05d6-5f6a-8aa0-df07fc6d4c87', 'e702018a-6286-5577-805f-f99d921df07d', 12, 'ACT-12', 'Monitor and promote good agricultural practices / (CamGAP) and organic farming for cashew crops.', 'MAFF', 'active'),
  ('3cddb56f-47c0-50d6-af03-df2815e565bf', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '6b614d37-5828-56bb-8de3-cefcff6d2a91', 'e702018a-6286-5577-805f-f99d921df07d', 13, 'ACT-13', 'Create a budget package to mitigate the difficulties of farmers and processing plants in the event of natural disasters, epidemics, border closures, market disruptions, and flooding at harvest time.', 'MEF, ARDB, SMEs Bank', 'active'),
  ('127a319f-aa56-5d7e-b791-00fc9f60c2da', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', 'd99806f1-7ea4-5067-ad5a-bc3bf298d112', 'e702018a-6286-5577-805f-f99d921df07d', 14, 'ACT-14', 'Encourage banks and financial institutions to increase agricultural loan products or to adjust existing products to facilitate and lower interest rates.', 'NBC', 'active'),
  ('4c7cbc64-edd8-51d7-90b7-da98b048be51', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '6dcedc5e-82a6-5572-b9fa-8061323da7fa', 'e702018a-6286-5577-805f-f99d921df07d', 15, 'ACT-15', 'Examine the possibility of constructing irrigation systems and other water sources to supply cashew crop production.', 'MOWRAM', 'active'),
  ('a58366a9-7402-5688-a874-d025dae9463e', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '492869f3-3b78-5020-ad22-ccd857abe005', 'e702018a-6286-5577-805f-f99d921df07d', 16, 'ACT-16', 'Prioritise demining plans to clear mines and unexploded ordnance for cashew plantations', 'CMAA', 'active'),
  ('30321e6e-ba3c-5a10-8bfe-2a715f4cfe31', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', 'e6be42ca-e027-5690-ad9b-ed3f18b8fe46', 'e702018a-6286-5577-805f-f99d921df07d', 17, 'ACT-17', 'Include the cashew sector in strategic development plans and investment programs and cooperate with local communities and development partners to build and improve access roads to farms in accordance with the resources of subsidy fund collections.', 'MRD, Provincial', 'active'),
  ('3d3a75e5-50e7-5c5e-85e6-f23bdfc23710', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '366b5a6a-2747-53f3-b285-68b0532c68e8', 'fbcf6bde-d4fb-5cec-a2dd-cf4dcdc6b9ff', 18, 'ACT-18', 'Encourage the private sector to invest in processing cashew products for the domestic and export markets.', 'CDC, MOC, MISTI, MOT', 'active'),
  ('764e71ee-51fb-503e-8cf1-63535cdcebfc', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '4d321f73-86f9-5a51-8a64-afb9af7ab1fe', 'fbcf6bde-d4fb-5cec-a2dd-cf4dcdc6b9ff', 19, 'ACT-19', 'Encourage cashew processing factories to develop cashew processing capacity with the transfer of processing industry technologies for food production and cashew waste.', 'MISTI, MOE, CDC', 'active'),
  ('9f910ae8-ef1c-5f00-be5b-7d88c2980afd', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '366b5a6a-2747-53f3-b285-68b0532c68e8', 'fbcf6bde-d4fb-5cec-a2dd-cf4dcdc6b9ff', 20, 'ACT-20', 'Study the economic benefits and encourage the private sector to establish cashew processing areas, which are located within cashew plantations or in industrial parks, in one location, in provinces that have potential for domestic supply. The establishment of such a processing / area could add great value to the rural economy.', 'MOC, CDC, Line Ministries', 'active'),
  ('219332fa-727c-5f22-b3dd-f4abd0df2b66', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '4d321f73-86f9-5a51-8a64-afb9af7ab1fe', 'fbcf6bde-d4fb-5cec-a2dd-cf4dcdc6b9ff', 21, 'ACT-21', 'Encourage the processing and management of cashew products for use as final products or semi- products to produce various final products.', 'MISTI', 'active'),
  ('46c2b0a2-7a26-5991-afdd-901e33e721cb', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '4a89738f-f6d4-56fb-9ada-b72427055ca0', 'fbcf6bde-d4fb-5cec-a2dd-cf4dcdc6b9ff', 22, 'ACT-22', 'Provide technical advice about cashew processing plants to effectively manage waste, lower environmental impacts, and increase value-added from recycling cashew processing waste.', 'MOE, MISTI, Line Ministries, Provincial', 'active'),
  ('c21f4c5d-eeb0-57fa-911b-cd0596827c75', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '4d321f73-86f9-5a51-8a64-afb9af7ab1fe', 'fbcf6bde-d4fb-5cec-a2dd-cf4dcdc6b9ff', 23, 'ACT-23', 'Study and create standards related to cashew kernels, prepare procedures for recognising and implementing these standards according to the needs of importing countries. This would boost the quality and sustainability of Cambodian cashew processing by providing technical support and building capacity for processors so that they can obtain food standard certificates.', 'MISTI', 'active'),
  ('35f63c36-aff8-5dd8-9e93-738e54768c18', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '4d321f73-86f9-5a51-8a64-afb9af7ab1fe', 'fbcf6bde-d4fb-5cec-a2dd-cf4dcdc6b9ff', 24, 'ACT-24', 'Guide and facilitate cashew processing enterprises and factories to enhance export productivity, ensure quality and food safety to a minimum level in accordance with the quality control system or standards, international food safety and management system, or equivalent systems certified by an accredited certification body.', 'MISTI', 'active'),
  ('edf0c4bc-93b6-5675-91e3-68294643d159', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '6b614d37-5828-56bb-8de3-cefcff6d2a91', 'fbcf6bde-d4fb-5cec-a2dd-cf4dcdc6b9ff', 25, 'ACT-25', 'Examine the possibility of providing incentives through the exemption of, or reduction in, income tax, tax on processed cashew products, and value- added tax, to legal cashew operators who are able / to provide direct benefits to farmers.', 'MEF', 'active'),
  ('2a07e995-426a-5b3f-a51c-fbb3da2d9f17', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '931764f5-d297-5d5b-a461-bed8bfe7897b', 'fbcf6bde-d4fb-5cec-a2dd-cf4dcdc6b9ff', 26, 'ACT-26', 'Examine the feasibility and provide the private sector with the necessary incentives to invest in, for instance, the construction of cashew warehouses at key strategic locations to store cashew products for year-round processing.', 'GDCD, MEF', 'active'),
  ('f2aa02be-8cbe-5eed-9067-8c6e246acc1c', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '366b5a6a-2747-53f3-b285-68b0532c68e8', 'fbcf6bde-d4fb-5cec-a2dd-cf4dcdc6b9ff', 27, 'ACT-27', 'Mobilise investors to build drying yards and warehouses at key strategic locations for managing the harvest and the storage of cashew products for processing.', 'MOC, CDC', 'active'),
  ('61ecdbe4-3b86-5a1d-b5d7-9e184528ef44', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '07ef992d-7414-5835-b990-40defaea8fa0', 'fbcf6bde-d4fb-5cec-a2dd-cf4dcdc6b9ff', 28, 'ACT-28', 'Examine the possibility of facilitating a reduction in electricity prices for consumers in the cashew sector.', 'MME, EAC', 'active'),
  ('6b9f7c27-d48d-5a95-85da-8278d3968acb', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '69152697-bb7b-5e6c-814c-c8362f1c9c25', 'cf3a5934-6434-584d-8206-0607612cc5c3', 29, 'ACT-29', 'Strengthen market information and data collection services for farmers and the public through various media so that they can monitor the market situation.', 'MOC, MAFF, MOT', 'active'),
  ('2bf0f60f-f802-58c3-9fae-0594eea57493', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '69152697-bb7b-5e6c-814c-c8362f1c9c25', 'cf3a5934-6434-584d-8206-0607612cc5c3', 30, 'ACT-30', 'Facilitate the establishment of cashew trade associations or federations to gather together the private sector, exporters, processors and operators involved in the cashew business.', 'MOC, MOT', 'active'),
  ('f818d472-eaea-5241-93b8-222fe0aef1df', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '69152697-bb7b-5e6c-814c-c8362f1c9c25', 'cf3a5934-6434-584d-8206-0607612cc5c3', 31, 'ACT-31', 'Examine market trends, regional competition, and value-chains in order to promote the development of the cashew sector so that it is / consistent and inclusive.', 'MOC', 'active'),
  ('74aa81e8-af5d-59db-8e38-e11e1ce9c8b9', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '69152697-bb7b-5e6c-814c-c8362f1c9c25', 'cf3a5934-6434-584d-8206-0607612cc5c3', 32, 'ACT-32', 'Continue to negotiate with export target countries about tariff exemptions or reductions, quotas, and trade facilitation, especially the effective implementation of the One Window Service Office (OWSO) mechanism.', 'MOC', 'active'),
  ('ce7b3251-b757-522b-988c-30733348eb95', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '6bc9a480-05d6-5f6a-8aa0-df07fc6d4c87', 'cf3a5934-6434-584d-8206-0607612cc5c3', 33, 'ACT-33', 'Promote negotiations with target countries about facilitating the implementation of sanitary and phytosanitary rules, and build the capacity of Cambodian exporters and stakeholders to be able to comply with sanitation and phytosanitary standards. This can be achieved by encouraging and opening up the private sector to participate in the provision of sanitation and phytosanitary services.', 'MAFF', 'active'),
  ('9a7527d8-5abb-59c7-9035-336f70229a79', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '4d321f73-86f9-5a51-8a64-afb9af7ab1fe', 'cf3a5934-6434-584d-8206-0607612cc5c3', 34, 'ACT-34', 'Promote and disseminate information about the benefits of branding and packaging with quality and standards.', 'MOC, MISTI, MOT', 'active'),
  ('912236ad-fc24-57e6-b049-2e7846c66a28', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '69152697-bb7b-5e6c-814c-c8362f1c9c25', 'cf3a5934-6434-584d-8206-0607612cc5c3', 35, 'ACT-35', 'Promote and build a good branding reputation about products, using all means to widely disseminate this brand, to increase market competitiveness.', 'MOC', 'active'),
  ('96a8a5ab-af50-59ba-8962-00138dfcf17b', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '4d321f73-86f9-5a51-8a64-afb9af7ab1fe', 'cf3a5934-6434-584d-8206-0607612cc5c3', 36, 'ACT-36', 'Facilitate the certificate provision mechanism for food product hygiene and strengthen the laboratory capacity in accordance with international standards. The operation of this laboratory may involve a public-private partnership.', 'MISTI', 'active'),
  ('0fcc2d83-2a91-5df6-9202-e503a954d2c9', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', 'cebfc433-5935-512b-8cf5-730b5541b634', 'cf3a5934-6434-584d-8206-0607612cc5c3', 37, 'ACT-37', 'Promote and facilitate the development of new digital technologies for electronic business operations.', 'MOC, MPWT, NBC', 'active'),
  ('6c231a13-56e9-581d-8acf-3fd1c68ab10f', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '69152697-bb7b-5e6c-814c-c8362f1c9c25', 'cf3a5934-6434-584d-8206-0607612cc5c3', 38, 'ACT-38', 'Develop new digital mechanisms and techniques to promote a well-recognised and confident marketing platform to sellers and buyers.', 'MOC', 'active'),
  ('42496901-e1df-5205-a3bb-fdef68a5b550', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '69152697-bb7b-5e6c-814c-c8362f1c9c25', 'cf3a5934-6434-584d-8206-0607612cc5c3', 39, 'ACT-39', 'Organise a cashew business forum to promote Cambodia''s cashew products and connect the private sector to international business networks.', 'MOC', 'active'),
  ('b4403cb2-cf86-53b6-9ab9-b2317c66e88b', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '69152697-bb7b-5e6c-814c-c8362f1c9c25', 'cf3a5934-6434-584d-8206-0607612cc5c3', 40, 'ACT-40', 'Launch a campaign about the use of local cashew products.', 'MOC, MOT', 'active'),
  ('29c60b7d-0ec8-5264-b002-94f91fed889f', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '9291098c-559b-5845-b82a-b0b1cd8b7485', 'cf3a5934-6434-584d-8206-0607612cc5c3', 41, 'ACT-41', 'Promote and establish agro-tourism markets for cashew products on site.', 'MOT, MAFF, MOC, Provinical', 'active'),
  ('06747c7b-ab70-57ae-82d5-ee75d3714399', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '92b6de25-ba0c-58ea-8c21-469c1dd5978b', 'cf3a5934-6434-584d-8206-0607612cc5c3', 42, 'ACT-42', 'Continue to build the necessary physical infrastructure to connect factories, enterprises, and special economic zones to ports and export / gates.', 'MPWT', 'active'),
  ('95de73ea-b6be-5daa-8fb9-a7119e512ffc', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '69152697-bb7b-5e6c-814c-c8362f1c9c25', 'cf3a5934-6434-584d-8206-0607612cc5c3', 43, 'ACT-43', 'Coordinate export procedures to reduce costs and increase the competitiveness of Cambodia’s cashew products.', 'MOC, MAFF, MISTI, MEF', 'active'),
  ('98b2d269-259f-5f3f-a72e-0b9cdf71c1be', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '8820e37f-9611-5f70-9e17-07338290e329', '92b6de25-ba0c-58ea-8c21-469c1dd5978b', 'cf3a5934-6434-584d-8206-0607612cc5c3', 44, 'ACT-44', 'Examine the possibility to reduce service fees, and to conduct the export process with speed and efficiency. The possibility of building standard warehouses for all agricultural products should also be explored.', 'MPWT, MEF, Line Ministries, Provincial, MOC', 'active');
